style.css:
@-moz-document domain("google.com") {
/* Altera o fundo geral da página */
    body, #gsr, #viewport {
        background-image: url("https://squarespace-cdn.com") !important;
        background-size: cover !important;       /* Faz a imagem cobrir a tela inteira */
        background-position: center !important;   /* Centraliza o logo na tela */
        background-repeat: no-repeat !important;  /* Impede que a imagem fique se repetindo */
        background-attachment: fixed !important;  /* Mantém o fundo fixo ao rolar */
    }

    /* Deixa as caixas de textos brancas do Google transparentes para revelar o fundo */
    .content, #cnt, .sfbg, .goxvbe, .KxwPGc {
        background: transparent !important;
    }

    /* Ajusta os textos menores do rodapé para ficarem visíveis em branco */
    a, span, footer, .FXwZgc {
        color: #ffffff !important;
    }
}
